style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-color: #ffe6f0 !important;
    color: #800040 !important;
  }

  .navbar, .header, .nav-menu, .top-nav {
    background-color: #ffb6c1 !important;
    border-color: #ff99cc !important;
  }

  a, a:visited {
    color: #cc0077 !important;
  }

  button, .btn-primary, .btn-secondary {
    background-color: #ff69b4 !important;
    border-color: #ff1493 !important;
    color: white !important;
  }

  .container, .content, .section, .card, .game-card {
    background-color: #fff0f5 !important;
    border-radius: 10px !important;
  }

  .text, .label, .username, .description {
    color: #800040 !important;
  }

  /* Game thumbnails and icons with rounded pink borders */
  img {
    border: 3px solid #ffb6c1 !important;
    border-radius: 8px !important;
  }

  /* Hide annoying ads (optional) */
  .ad-container, .ads, .sponsored {
    display: none !important;
  }
}
